// Replace these non-secret example values. Keep the API key in Header Auth credentials.
const config = { apiOrigin: 'https://api.insidedm.in', intentKey: 'orders/REPLACE_ORDER_ID/shipped/v1', phone: 'REPLACE_WITH_E164', templateId: 'REPLACE_WITH_APPROVED_TEMPLATE_ID', variables: { customer_name: 'Asha' } };
if (Object.values(config).some(value => typeof value === 'string' && value.includes('REPLACE')) || !/^\+[1-9]\d{7,14}$/.test(config.phone)) throw new Error('Configure a real source intent key, recipient and approved template first.');
return [{ json: config }];
